body.script:
//
document.querySelectorAll('input[name="visa_type"]').forEach(function(r){
    r.addEventListener('change',function(){
        var isEmp=this.value==='employee';
        document.getElementById('sb-emp').style.display=isEmp?'flex':'none';
        document.getElementById('decl-n').textContent=isEmp?'5':'4';
        document.getElementById('rev-n').textContent=isEmp?'6':'5';
        document.getElementById('pay-n').textContent=isEmp?'7':'6';
    });
});

function eidStep1Validate() {
  var vt = document.querySelector('input[name="visa_type"]:checked');
  if (!vt) {
    document.getElementById('visa_type_err').style.display='block';
    return;
  }
  document.getElementById('visa_type_err').style.display='none';
  document.querySelector('form').submit();
}
//
//

//
var unavail=['accountant_manager','business_development_manager','finance_manager'];
function checkDesig(v){document.getElementById('desig_flag').value=unavail.indexOf(v)!==-1?'1':'0';document.getElementById('desig-warn').style.display=unavail.indexOf(v)!==-1?'block':'none';}
function checkQual(v){var d=['diploma','bachelors','masters','doctorate'];document.getElementById('degree-upload').style.display=d.indexOf(v)!==-1?'block':'none';}
function toggleDep(v){document.getElementById('dep-yes').classList.toggle('selected',v==='yes');document.getElementById('dep-no').classList.toggle('selected',v==='no');document.getElementById('dep-details').style.display=v==='yes'?'block':'none';}
var dv=document.getElementById('desig_sel').value; if(dv) checkDesig(dv);
var qv=document.getElementById('qual_sel').value; if(qv) checkQual(qv);

function eidStep2Validate() {
  var valid = true;
  function showErr(id,msg){var el=document.getElementById(id);if(el){el.textContent=msg;el.style.display="block";}}
  function hideErr(id){var el=document.getElementById(id);if(el)el.style.display="none";}

  var gen = document.querySelector('input[name="gender"]:checked');
  if (!gen) { showErr('gender_err','Please select gender.'); valid=false; } else hideErr('gender_err');

  var fn = document.querySelector('[name="first_name"]');
  var fnv = fn ? fn.value.trim() : '';
  if (fnv.length < 3 || fnv.length > 50) { showErr('fname_err','First name must be 3-50 characters.'); valid=false; } else hideErr('fname_err');

  var ln = document.querySelector('[name="last_name"]');
  var lnv = ln ? ln.value.trim() : '';
  if (lnv.length < 3 || lnv.length > 50) { showErr('lname_err','Last name must be 3-50 characters.'); valid=false; } else hideErr('lname_err');

  var fat = document.querySelector('[name="father_name"]');
  var fatv = fat ? fat.value.trim() : '';
  if (fatv.length < 3 || fatv.length > 50) { showErr('fatname_err',"Father's name must be 3-50 characters."); valid=false; } else hideErr('fatname_err');

  var mot = document.querySelector('[name="mother_name"]');
  var motv = mot ? mot.value.trim() : '';
  if (motv.length < 3 || motv.length > 50) { showErr('motname_err',"Mother's name must be 3-50 characters."); valid=false; } else hideErr('motname_err');

  var ph = document.querySelector('[name="phone"]');
  var phv = ph ? ph.value.trim().replace(/\D/g,'') : '';
  if (phv.length < 10 || phv.length > 15) { showErr('phone_err','Phone number must be 10-15 digits.'); valid=false; } else hideErr('phone_err');

  var em = document.querySelector('[name="applicant_email"]');
  var emv = em ? em.value.trim() : '';
  if (!emv || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emv)) { showErr('email_err','Please enter a valid email address.'); valid=false; } else hideErr('email_err');

  var addr = document.querySelector('[name="address"]');
  var addrv = addr ? addr.value.trim() : '';
  if (addrv.length < 5 || addrv.length > 500) { showErr('addr_err','Address must be 5-500 characters.'); valid=false; } else hideErr('addr_err');

  var ct = document.querySelector('[name="city"]');
  var ctv = ct ? ct.value.trim() : '';
  if (ctv.length < 5 || ctv.length > 500) { showErr('city_err','City must be 5-500 characters.'); valid=false; } else hideErr('city_err');

  var dob = document.querySelector('[name="dob"]');
  if (!dob || !dob.value) { showErr('dob_err','Please select date of birth.'); valid=false; } else hideErr('dob_err');

  var cid = document.querySelector('[name="country_id"]');
  if (!cid || !cid.value) { showErr('country_err','Please select country.'); valid=false; } else hideErr('country_err');

  var nat = document.querySelector('[name="nationality_id"]');
  if (!nat || !nat.value) { showErr('nat_err','Please select nationality.'); valid=false; } else hideErr('nat_err');

  var pnat = document.querySelector('[name="prev_nationality_id"]');
  if (!pnat || !pnat.value) { showErr('prev_nat_err','Please select previous nationality.'); valid=false; } else hideErr('prev_nat_err');

  var ms = document.querySelector('[name="marital_status"]');
  if (!ms || !ms.value) { showErr('marital_err','Please select marital status.'); valid=false; } else hideErr('marital_err');

  var rel = document.querySelector('[name="religion"]');
  if (!rel || !rel.value) { showErr('religion_err','Please select religion.'); valid=false; } else hideErr('religion_err');

  var des = document.querySelector('[name="designation"]');
  if (!des || !des.value) { showErr('desig_err','Please select designation.'); valid=false; } else hideErr('desig_err');

  var qual = document.querySelector('[name="highest_qualification"]');
  if (!qual || !qual.value) { showErr('qual_err','Please select highest qualification.'); valid=false; } else hideErr('qual_err');

  var dep = document.querySelector('input[name="has_dependents"]:checked');
  if (!dep) { showErr('dep_err','Please select dependent sponsorship option.'); valid=false; } else hideErr('dep_err');

    // Document upload validation
  var docFields = ['doc_photo','doc_evisa','doc_change_status','doc_medical','doc_emp_contract_copy','doc_eid_copy'];
  var docOk = true;
  docFields.forEach(function(name){
    var inp = document.querySelector('input[name="'+name+'"]');
    if (!inp || inp.files.length === 0) docOk = false;
  });
  if (!docOk) { showErr('doc_upload_err','Please upload all required documents.'); valid=false; } else hideErr('doc_upload_err');

  if (valid) document.querySelector('form').submit();
}
//
//

//
function togglePrevVisa(v){
    document.getElementById('prev-yes').classList.toggle('selected',v==='yes');
    document.getElementById('prev-no').classList.toggle('selected',v==='no');
    document.getElementById('prev-visa-yes-fields').style.display=v==='yes'?'block':'none';
    document.getElementById('prev-visa-no-fields').style.display=v==='no'?'block':'none';
    document.getElementById('sec-pobox').style.display=v==='yes'?'flex':'none';
    // deliver section always visible - no change here
}
function togglePoBox(v){
    document.getElementById('pobox-fields').style.display=v==='yes'?'block':'none';
}
function toggleDeliverAddr(v){
    document.getElementById('delivery-addr-fields').style.display=v==='yes'?'block':'none';
}
var pv=document.querySelector('input[name="prev_residence_visa"]:checked');
if(pv) togglePrevVisa(pv.value);
var pb=document.querySelector('input[name="has_uae_pobox"]:checked');
if(pb) togglePoBox(pb.value);
var dv=document.querySelector('input[name="deliver_physical_eid"]:checked');
if(dv) toggleDeliverAddr(dv.value);

function eidStep3Validate() {
  var valid = true;
  function showErr(id,msg){var el=document.getElementById(id);if(el){el.textContent=msg;el.style.display="block";}}
  function hideErr(id){var el=document.getElementById(id);if(el)el.style.display="none";}
  var pv = document.querySelector('input[name="prev_residence_visa"]:checked');
  if (!pv) { showErr('prev_visa_err','Please select yes or no.'); valid=false; } else {
    hideErr('prev_visa_err');
    if (pv.value === 'yes') {
      var eid = document.querySelector('[name="eid_number"]');
      var eidv = eid ? eid.value.trim() : '';
      var eidRe = /^784-\d{4}-\d{7}-\d$/;
      if (!eidRe.test(eidv)) { showErr('eid_num_err','Emirates ID must be in format 784-XXXX-XXXXXXX-X.'); valid=false; } else hideErr('eid_num_err');
      var eidExp = document.querySelector('[name="eid_expiry"]');
      if (!eidExp || !eidExp.value) { showErr('eid_exp_err','Please select Emirates ID expiry date.'); valid=false; } else hideErr('eid_exp_err');
      var pb = document.querySelector('input[name="has_uae_pobox"]:checked');
      if (!pb) { showErr('pobox_err','Please select PO Box option.'); valid=false; } else {
        hideErr('pobox_err');
        if (pb.value === 'yes') {
          var pbn = document.querySelector('[name="pobox_number"]');
          var pbnv = pbn ? pbn.value.trim() : '';
          if (!pbnv || !/^\d{1,10}$/.test(pbnv)) { showErr('pobox_num_err','PO Box number must be 1-10 digits.'); valid=false; } else hideErr('pobox_num_err');
        } else hideErr('pobox_num_err');
      }
      var centerEl = document.querySelector('select[name="biometric_center"]');
      if (!centerEl || !centerEl.value) { showErr('center_err','Please select a preferred center location.'); valid=false; } else hideErr('center_err');
      var visibleMobile = '';
      document.querySelectorAll('input[name="biometric_mobile"]').forEach(function(inp){
        if (inp.offsetParent !== null) visibleMobile = inp.value.trim().replace(/\D/g,'');
      });
      if (visibleMobile.length < 10 || visibleMobile.length > 15) { showErr('bio_phone_err','Mobile number must be 10-15 digits.'); valid=false; } else hideErr('bio_phone_err');
    } else {
      hideErr('eid_num_err'); hideErr('eid_exp_err');
      hideErr('pobox_err'); hideErr('pobox_num_err');
      hideErr('center_err'); hideErr('bio_phone_err');
    }
  }
  var deid = document.querySelector('input[name="deliver_physical_eid"]:checked');
  if (!deid) { showErr('deliver_err','Please select EID delivery option.'); valid=false; } else {
    hideErr('deliver_err');
    if (deid.value === 'yes') {
      var dc = document.querySelector('[name="delivery_city"]');
      if (!dc || !dc.value) { showErr('del_city_err','Please select delivery city.'); valid=false; } else hideErr('del_city_err');
      var lm = document.querySelector('[name="delivery_landmark"]');
      var lmv = lm ? lm.value.trim() : '';
      if (lmv.length < 5 || lmv.length > 50) { showErr('del_lmark_err','Landmark must be 5-50 characters.'); valid=false; } else hideErr('del_lmark_err');
      var da = document.querySelector('[name="delivery_address"]');
      if (!da || !da.value.trim()) { showErr('del_addr_err','Please enter delivery address.'); valid=false; } else hideErr('del_addr_err');
      var dp = document.querySelector('[name="delivery_phone"]');
      var dpv = dp ? dp.value.trim().replace(/\D/g,'') : '';
      if (dpv.length < 10 || dpv.length > 15) { showErr('del_phone_err','Phone number must be 10-15 digits.'); valid=false; } else hideErr('del_phone_err');
    } else {
      hideErr('del_city_err'); hideErr('del_lmark_err');
      hideErr('del_addr_err'); hideErr('del_phone_err');
    }
  }
  if (valid) document.querySelector('form').submit();
}function eidStep4Validate_disabled() {
  var valid = true;
  function showErr(id,msg){var el=document.getElementById(id);if(el){el.textContent=msg;el.style.display="block";}}
  function hideErr(id){var el=document.getElementById(id);if(el)el.style.display="none";}

  var ct = document.querySelector('input[name="contract_type"]:checked');
  if (!ct) { showErr('contract_err','Please select contract type.'); valid=false; } else {
    hideErr('contract_err');
    if (ct.value === '2yr_limited') {
      var prob = document.querySelector('input[name="probation_period"]:checked');
      if (!prob) { showErr('prob_err','Please select probation period.'); valid=false; } else hideErr('prob_err');

      var np = document.querySelector('[name="notice_period"]');
      var npv = np ? np.value.trim() : '';
      if (npv.length < 5 || npv.length > 100) { showErr('notice_err','Notice period must be 5-100 characters.'); valid=false; } else hideErr('notice_err');

      var sb = document.querySelector('[name="salary_basic"]');
      if (!sb || !sb.value) { showErr('sal_basic_err','Please enter basic salary.'); valid=false; } else hideErr('sal_basic_err');

      var sa = document.querySelector('[name="salary_accommodation"]');
      if (!sa || !sa.value) { showErr('sal_acc_err','Please enter accommodation allowance.'); valid=false; } else hideErr('sal_acc_err');

      var st = document.querySelector('[name="salary_transport"]');
      if (!st || !st.value) { showErr('sal_trans_err','Please enter transport allowance.'); valid=false; } else hideErr('sal_trans_err');

      var so = document.querySelector('[name="salary_other"]');
      if (!so || !so.value) { showErr('sal_other_err','Please enter other allowance.'); valid=false; } else hideErr('sal_other_err');

      var stot = document.querySelector('[name="salary_total"]');
      if (!stot || !stot.value) { showErr('sal_total_err','Please enter total remuneration.'); valid=false; } else hideErr('sal_total_err');

      var ed = document.querySelector('[name="contract_execution"]');
      if (!ed || !ed.value) { showErr('exec_date_err','Please select contract execution date.'); valid=false; } else hideErr('exec_date_err');

      var sd = document.querySelector('[name="contract_start"]');
      if (!sd || !sd.value) { showErr('start_date_err','Please select contract start date.'); valid=false; } else hideErr('start_date_err');

      var cd = document.querySelector('[name="contract_end"]');
      if (!cd || !cd.value) { showErr('end_date_err','Please select contract end date.'); valid=false; } else hideErr('end_date_err');
    }
  }

  if (valid) document.querySelector('form').submit();
}
//
//

//
// Auto-calculate total
document.querySelectorAll('#salary_basic,#salary_accommodation,#salary_transport,#salary_other').forEach(function(el){
  el.addEventListener('input',function(){
    var b=parseFloat(document.getElementById('salary_basic').value)||0;
    var a=parseFloat(document.getElementById('salary_accommodation').value)||0;
    var t=parseFloat(document.getElementById('salary_transport').value)||0;
    var o=parseFloat(document.getElementById('salary_other').value)||0;
    document.getElementById('salary_total').value=(b+a+t+o).toFixed(2);
  });
});
function toggleContractSections(v){
  document.getElementById('sec-contract-details').style.display=v==='2yr_limited'?'flex':'none';
  document.getElementById('upload-num').textContent=v==='2yr_limited'?'03':'02';
}
// attach listeners
document.querySelectorAll('input[name="contract_type"]').forEach(function(r){
  r.addEventListener('change',function(){ toggleContractSections(this.value); });
});
var checked=document.querySelector('input[name="contract_type"]:checked');
if(checked) toggleContractSections(checked.value);

function eidStep4Validate(){
  var valid=true;
  function showErr(id,msg){var el=document.getElementById(id);if(el){el.textContent=msg;el.style.display="block";}}
  function hideErr(id){var el=document.getElementById(id);if(el)el.style.display="none";}
  var ct=document.querySelector('input[name="contract_type"]:checked');
  if(!ct){showErr('contract_err','Please select contract type.');valid=false;}else{
    hideErr('contract_err');
    if(ct.value==='2yr_limited'){
      var prob=document.querySelector('input[name="probation_period"]:checked');
      if(!prob){showErr('prob_err','Please select probation period.');valid=false;}else hideErr('prob_err');
      var np=document.querySelector('[name="notice_period"]');
      var npv=np?np.value.trim():'';
      if(npv.length<5||npv.length>100){showErr('notice_err','Notice period must be 5-100 characters.');valid=false;}else hideErr('notice_err');
      var sb=document.querySelector('[name="salary_basic"]');
      if(!sb||!sb.value){showErr('sal_basic_err','Please enter basic salary.');valid=false;}else hideErr('sal_basic_err');
      var sa=document.querySelector('[name="salary_accommodation"]');
      if(!sa||!sa.value){showErr('sal_acc_err','Please enter accommodation allowance.');valid=false;}else hideErr('sal_acc_err');
      var st=document.querySelector('[name="salary_transport"]');
      if(!st||!st.value){showErr('sal_trans_err','Please enter transport allowance.');valid=false;}else hideErr('sal_trans_err');
      var so=document.querySelector('[name="salary_other"]');
      if(!so||!so.value){showErr('sal_other_err','Please enter other allowance.');valid=false;}else hideErr('sal_other_err');
      var stot=document.querySelector('[name="salary_total"]');
      if(!stot||!stot.value){showErr('sal_total_err','Please enter total remuneration.');valid=false;}else hideErr('sal_total_err');
      var ed=document.querySelector('[name="contract_execution"]');
      if(!ed||!ed.value){showErr('exec_date_err','Please select contract execution date.');valid=false;}else hideErr('exec_date_err');
      var sd=document.querySelector('[name="contract_start"]');
      if(!sd||!sd.value){showErr('start_date_err','Please select contract start date.');valid=false;}else hideErr('start_date_err');
      var cd=document.querySelector('[name="contract_end"]');
      if(!cd||!cd.value){showErr('end_date_err','Please select contract end date.');valid=false;}else hideErr('end_date_err');
    }
  }
  // File upload validation - at least one file required
  var fileInput = document.querySelector('input[name="doc_contract"]');
  var hasExisting = document.querySelector('.doc-contract-existing');
  if (fileInput && fileInput.files.length === 0 && !hasExisting) {
    showErr('doc_contract_err','Please upload at least one contract document.');
    valid=false;
  } else {
    hideErr('doc_contract_err');
  }

  if(valid)document.querySelector('form').submit();
}
//
//

//
function eidDeclValidate() {
  var decl = document.querySelector('[name="declaration_accepted"]');
  if (!decl || !decl.checked) {
    document.getElementById('eid_decl_err').style.display='block';
    return;
  }
  document.getElementById('eid_decl_err').style.display='none';
  document.querySelector('form').submit();
}
